import{_ as p,r as s,o,c,e as a,a as l,s as u}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Планирование задач - October CMS - 3.x","titleTemplate":false,"description":"Выполняйте запланированные задачи практически для чего угодно.","frontmatter":{"subtitle":"Выполняйте запланированные задачи практически для чего угодно."},"headers":[{"level":2,"title":"Определение расписаний","slug":"определение-расписании","link":"#определение-расписании","children":[{"level":3,"title":"Параметры частоты расписания","slug":"параметры-частоты-расписания","link":"#параметры-частоты-расписания","children":[{"level":4,"title":"Ограничения проверкой условия","slug":"ограничения-проверкои-условия","link":"#ограничения-проверкои-условия","children":[]}]},{"level":3,"title":"Предотвращение перекрытия задач","slug":"предотвращение-перекрытия-задач","link":"#предотвращение-перекрытия-задач","children":[]}]},{"level":2,"title":"Вывод задач","slug":"вывод-задач","link":"#вывод-задач","children":[]},{"level":2,"title":"Хуки задач","slug":"хуки-задач","link":"#хуки-задач","children":[{"level":4,"title":"Пинг URL","slug":"пинг-url","link":"#пинг-url","children":[]}]}],"relativePath":"3.x/ru/extend/system/scheduling.md","filePath":"3.x/ru/extend/system/scheduling.md"}'),d={name:"3.x/ru/extend/system/scheduling.md"};function i(r,n,k,g,h,f){const t=s("pre-heading"),e=s("post-heading");return o(),c("div",null,[a(t),n[0]||(n[0]=l("h1",null,"Планирование задач",-1)),a(e),n[1]||(n[1]=u(`<div class="custom-block aside"><p>Инструкции по настройке задачи планировщика см. в <a href="./../../setup/installation.html">руководстве по установке</a>.</p></div><p>Раньше разработчикам приходилось создавать отдельную запись Cron для каждой задачи, которую нужно было запланировать. Однако это порой доставляло неудобства. Расписание задач не находилось под контролем версий, и для добавления записей Cron приходилось подключаться к серверу по SSH. Планировщик команд позволяет гибко и выразительно определять расписание команд прямо в самом приложении, и на сервере требуется только одна запись Cron.</p><p><a id="oc-defining-schedules"></a></p><h2 id="определение-расписании"><a href="#определение-расписании" class="header-anchor">#</a> Определение расписаний</h2><p>Все запланированные задачи можно определить, переопределив метод <code>registerSchedule</code> в <a href="./../extending.html">файле регистрации плагина</a>. Метод принимает единственный аргумент <code>$schedule</code> и используется для определения команд вместе с их частотой выполнения.</p><p>Для начала рассмотрим пример планирования задачи. В этом примере мы запланируем вызов <code>Closure</code> каждый день в полночь. Внутри <code>Closure</code> мы выполним запрос к базе данных для очистки таблицы:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Plugin</span> <span class="token keyword">extends</span> <span class="token class-name">PluginBase</span>
<span class="token punctuation">{</span>
    <span class="token comment">// ...</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerSchedule</span><span class="token punctuation">(</span><span class="token variable">$schedule</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$schedule</span><span class="token operator">-&gt;</span><span class="token function">call</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;recent_users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">delete</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">daily</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Помимо планирования вызовов <code>Closure</code>, вы также можете планировать <a href="./../console-commands.html">консольные команды</a> и команды операционной системы. Например, вы можете использовать метод <code>command</code> для планирования консольной команды:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$schedule</span><span class="token operator">-&gt;</span><span class="token function">command</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;cache:clear&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">daily</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Метод <code>exec</code> может использоваться для выполнения команды операционной системы:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$schedule</span><span class="token operator">-&gt;</span><span class="token function">exec</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;node /home/acme/script.js&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">daily</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="параметры-частоты-расписания"><a href="#параметры-частоты-расписания" class="header-anchor">#</a> Параметры частоты расписания</h3><p>Разумеется, существует множество вариантов расписания, которые вы можете назначить вашей задаче:</p><div class="table"><table tabindex="0"><thead><tr><th>Метод</th><th>Описание</th></tr></thead><tbody><tr><td><code>-&gt;cron(&#39;* * * * *&#39;);</code></td><td>Запуск задачи по пользовательскому расписанию Cron</td></tr><tr><td><code>-&gt;everyMinute();</code></td><td>Запуск задачи каждую минуту</td></tr><tr><td><code>-&gt;everyFiveMinutes();</code></td><td>Запуск задачи каждые пять минут</td></tr><tr><td><code>-&gt;everyTenMinutes();</code></td><td>Запуск задачи каждые десять минут</td></tr><tr><td><code>-&gt;everyThirtyMinutes();</code></td><td>Запуск задачи каждые тридцать минут</td></tr><tr><td><code>-&gt;hourly();</code></td><td>Запуск задачи каждый час</td></tr><tr><td><code>-&gt;daily();</code></td><td>Запуск задачи каждый день в полночь</td></tr><tr><td><code>-&gt;dailyAt(&#39;13:00&#39;);</code></td><td>Запуск задачи каждый день в 13:00</td></tr><tr><td><code>-&gt;twiceDaily(1, 13);</code></td><td>Запуск задачи ежедневно в 1:00 и 13:00</td></tr><tr><td><code>-&gt;weekly();</code></td><td>Запуск задачи каждую неделю</td></tr><tr><td><code>-&gt;monthly();</code></td><td>Запуск задачи каждый месяц</td></tr></tbody></table></div><p>Эти методы могут быть объединены с дополнительными ограничениями для создания ещё более точных расписаний, выполняющихся только в определённые дни недели. Например, для планирования команды еженедельно по понедельникам:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$schedule</span><span class="token operator">-&gt;</span><span class="token function">call</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// Runs once a week on Monday at 13:00...</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">weekly</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">mondays</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">at</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;13:00&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Ниже приведён список дополнительных ограничений расписания:</p><div class="table"><table tabindex="0"><thead><tr><th>Метод</th><th>Описание</th></tr></thead><tbody><tr><td><code>-&gt;weekdays();</code></td><td>Ограничить задачу рабочими днями</td></tr><tr><td><code>-&gt;sundays();</code></td><td>Ограничить задачу воскресеньем</td></tr><tr><td><code>-&gt;mondays();</code></td><td>Ограничить задачу понедельником</td></tr><tr><td><code>-&gt;tuesdays();</code></td><td>Ограничить задачу вторником</td></tr><tr><td><code>-&gt;wednesdays();</code></td><td>Ограничить задачу средой</td></tr><tr><td><code>-&gt;thursdays();</code></td><td>Ограничить задачу четвергом</td></tr><tr><td><code>-&gt;fridays();</code></td><td>Ограничить задачу пятницей</td></tr><tr><td><code>-&gt;saturdays();</code></td><td>Ограничить задачу субботой</td></tr><tr><td><code>-&gt;when(Closure);</code></td><td>Ограничить задачу на основе проверки условия</td></tr></tbody></table></div><h4 id="ограничения-проверкои-условия"><a href="#ограничения-проверкои-условия" class="header-anchor">#</a> Ограничения проверкой условия</h4><p>Метод <code>when</code> может использоваться для ограничения выполнения задачи на основе результата заданной проверки условия. Другими словами, если переданное <code>Closure</code> возвращает <code>true</code>, задача будет выполнена, при условии что никакие другие ограничивающие условия не препятствуют её запуску:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$schedule</span><span class="token operator">-&gt;</span><span class="token function">command</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;emails:send&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">daily</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">when</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token constant boolean">true</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="предотвращение-перекрытия-задач"><a href="#предотвращение-перекрытия-задач" class="header-anchor">#</a> Предотвращение перекрытия задач</h3><p>По умолчанию запланированные задачи будут запущены, даже если предыдущий экземпляр задачи всё ещё выполняется. Чтобы предотвратить это, используйте метод <code>withoutOverlapping</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$schedule</span><span class="token operator">-&gt;</span><span class="token function">command</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;emails:send&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">withoutOverlapping</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>В этом примере консольная команда <code>emails:send</code> будет запускаться каждую минуту, если она ещё не выполняется. Метод <code>withoutOverlapping</code> особенно полезен, если у вас есть задачи, время выполнения которых сильно варьируется, и вам не нужно точно предсказывать, сколько времени займёт данная задача.</p><h2 id="вывод-задач"><a href="#вывод-задач" class="header-anchor">#</a> Вывод задач</h2><p>Планировщик предоставляет несколько удобных методов для работы с выводом, генерируемым запланированными задачами. Во-первых, с помощью метода <code>sendOutputTo</code> вы можете направить вывод в файл для последующего изучения.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$schedule</span><span class="token operator">-&gt;</span><span class="token function">command</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;emails:send&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">daily</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">sendOutputTo</span><span class="token punctuation">(</span><span class="token variable">$filePath</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>С помощью метода <code>emailOutputTo</code> вы можете отправить вывод на электронную почту по указанному адресу. Обратите внимание, что вывод сначала должен быть направлен в файл с помощью метода <code>sendOutputTo</code>. Также перед отправкой вывода задачи по электронной почте необходимо настроить <a href="./../../setup/mail-config.html">почтовые сервисы</a>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$schedule</span><span class="token operator">-&gt;</span><span class="token function">command</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">daily</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">sendOutputTo</span><span class="token punctuation">(</span><span class="token variable">$filePath</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">emailOutputTo</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo@example.tld&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>Методы <code>emailOutputTo</code> и <code>sendOutputTo</code> доступны только для метода <code>command</code> и не поддерживаются для <code>call</code>.</p></div><h2 id="хуки-задач"><a href="#хуки-задач" class="header-anchor">#</a> Хуки задач</h2><p>С помощью методов <code>before</code> и <code>after</code> вы можете указать код, который будет выполняться до и после завершения запланированной задачи:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$schedule</span><span class="token operator">-&gt;</span><span class="token function">command</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;emails:send&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">daily</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">before</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// Task is about to start...</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">after</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// Task is complete...</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="пинг-url"><a href="#пинг-url" class="header-anchor">#</a> Пинг URL</h4><p>С помощью методов <code>pingBefore</code> и <code>thenPing</code> планировщик может автоматически выполнять пинг заданного URL до или после завершения задачи. Этот метод полезен для уведомления внешнего сервиса о том, что ваша запланированная задача начинается или завершена:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$schedule</span><span class="token operator">-&gt;</span><span class="token function">command</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;emails:send&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">daily</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">pingBefore</span><span class="token punctuation">(</span><span class="token variable">$url</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">thenPing</span><span class="token punctuation">(</span><span class="token variable">$url</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div>`,37))])}const y=p(d,[["render",i]]);export{v as __pageData,y as default};
